// Opens files one after another in the example app and checks that every
// replaced player is torn down: its threads exit and nothing crashes.
//
//   cd flutter/example && flutter test integration_test -d macos
//
// Needs the media generated by tool/regression.sh in /tmp/lychee-media.

import 'dart:io';

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:integration_test/integration_test.dart';
import 'package:lychee_player_example/main.dart';

const _media = [
  '/tmp/lychee-media/h264_aac.mp4',
  '/tmp/lychee-media/hevc10.mp4',
  '/tmp/lychee-media/vp9_opus.webm',
  '/tmp/lychee-media/rotated.mp4',
];

/// Thread names in this process, from `sample`, keyed by thread id.
Future<List<String>> _threadNames() async {
  final file = '${Directory.systemTemp.path}/lychee-sample-$pid.txt';
  await Process.run('sample', ['$pid', '1', '-file', file]);
  final names = <String, String>{};
  final pattern = RegExp(r'Thread_(\d+): (\S+)');
  for (final line in await File(file).readAsLines()) {
    final match = pattern.firstMatch(line);
    if (match != null) {
      names[match[1]!] = match[2]!;
    }
  }
  return names.values.toList();
}

Future<Map<String, int>> _countThreads() async {
  final names = await _threadNames();
  int count(bool Function(String) test) => names.where(test).length;
  return {
    'lychee': count((n) => n.startsWith('lychee-')),
    'audio-io': count((n) => n == 'com.apple.audio.IOThread.client'),
    'display-link': count((n) => n.contains('CVDisplayLink')),
  };
}

void main() {
  final binding = IntegrationTestWidgetsFlutterBinding.ensureInitialized();
  // macOS reports a fully covered window as hidden, and Flutter then stops
  // scheduling frames, so pump() would wait forever while the test runs
  // behind other windows. Ignore lifecycle changes and keep frames on.
  SystemChannels.lifecycle.setMessageHandler((_) async => null);
  binding.handleAppLifecycleStateChanged(AppLifecycleState.resumed);

  testWidgets('switching files releases the previous player', (tester) async {
    await tester.pumpWidget(const ExampleApp());

    Future<void> wait(Duration duration) async {
      await Future<void>.delayed(duration);
      await tester.pump();
    }

    Future<void> open(String path) async {
      await tester.enterText(find.byType(TextField), path);
      await tester.tap(find.text('Open'));
      await tester.pump();
    }

    await open(_media[0]);
    await wait(const Duration(milliseconds: 1500));
    final before = await _countThreads();
    final rssBefore = ProcessInfo.currentRss;

    for (var i = 0; i < 10; i++) {
      await open(_media[i % _media.length]);
      await wait(const Duration(milliseconds: 1500));
      expect(find.text('error'), findsNothing);
    }

    // Two opens in a row, so the second starts before the first has created
    // its player. Calls onPressed directly: a second synthetic tap that
    // quickly is not delivered.
    await tester.enterText(find.byType(TextField), _media[0]);
    final button = tester.widget<FilledButton>(find.byType(FilledButton));
    button.onPressed!();
    button.onPressed!();
    await tester.pump();
    await wait(const Duration(seconds: 3));

    final threads = await _countThreads();
    final rssGrowth = (ProcessInfo.currentRss - rssBefore) >> 20;
    // ignore: avoid_print
    print('threads before: $before, after: $threads, rss +$rssGrowth MB');
    // One player playing audio and video: demux + two decode threads.
    expect(threads['lychee'], 3);
    expect(threads['audio-io'], lessThanOrEqualTo(1));
    // CoreVideo pools display link threads; a leaked link would add one per
    // switch.
    expect(
      threads['display-link']!,
      lessThanOrEqualTo(before['display-link']! + 2),
    );
  });
}
